      map['header_text'] = Variable<String>(headerText);
    }
    if (!nullToAbsent || footerText != null) {
      map['footer_text'] = Variable<String>(footerText);
    }
    map['show_logo'] = Variable<bool>(showLogo);
    map['show_tax_summary'] = Variable<bool>(showTaxSummary);
    map['show_qr_code'] = Variable<bool>(showQrCode);
    {
      map['paper_size'] = Variable<String>(
        $PrintSettingsTable.$converterpaperSize.toSql(paperSize),
      );
    }
    map['margin_top'] = Variable<int>(marginTop);
    map['margin_bottom'] = Variable<int>(marginBottom);
    map['margin_left'] = Variable<int>(marginLeft);
    map['margin_right'] = Variable<int>(marginRight);
    map['font_size'] = Variable<int>(fontSize);
    if (!nullToAbsent || createdAt != null) {
