class Sequence extends DataClass implements Insertable<Sequence> {
  /// Primary Key — UUID string stored as TEXT.
  final String id;

  /// Foreign Key linking to `businesses.id` (CASCADE).
  final String businessId;

  /// Composite Foreign Key linking to `branches(business_id, id)` (NULL = global business sequence).
  final String? branchId;

  /// Document type string classification (`SalesInvoice`, `PurchaseInvoice`, etc.).
  final String documentType;

  /// Optional prefix string prepended to document numbers (e.g., `INV-`).
  final String? prefix;

  /// Optional suffix string appended to document numbers (e.g., `-2026`).
  final String? suffix;

  /// Current sequential value counter (64-bit integer, check >= 0).
  final int currentValue;

  /// Increment step value per document generation (check > 0).
  final int step;

  /// Zero-padding width for document number string formatting (check > 0).
  final int padding;

  /// Sequence counter reset frequency interval (`Never`, `Daily`, `Monthly`, `Yearly`).
  final SequenceResetFrequency resetFrequency;

  /// Date when the sequence counter was last reset to starting value.
  final DateTime? lastResetDate;
  const Sequence({
    required this.id,
    required this.businessId,
    this.branchId,
    required this.documentType,
    this.prefix,
    this.suffix,
    required this.currentValue,
    required this.step,
    required this.padding,
    required this.resetFrequency,
    this.lastResetDate,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['business_id'] = Variable<String>(businessId);
    if (!nullToAbsent || branchId != null) {
      map['branch_id'] = Variable<String>(branchId);
    }
    map['document_type'] = Variable<String>(documentType);
    if (!nullToAbsent || prefix != null) {
      map['prefix'] = Variable<String>(prefix);
    }
    if (!nullToAbsent || suffix != null) {
      map['suffix'] = Variable<String>(suffix);
    }
    map['current_value'] = Variable<int>(currentValue);
    map['step'] = Variable<int>(step);
    map['padding'] = Variable<int>(padding);
    {
      map['reset_frequency'] = Variable<String>(
        $SequencesTable.$converterresetFrequency.toSql(resetFrequency),
      );
    }
    if (!nullToAbsent || lastResetDate != null) {
      map['last_reset_date'] = Variable<DateTime>(lastResetDate);
    }
    return map;
  }

  SequencesCompanion toCompanion(bool nullToAbsent) {
    return SequencesCompanion(
      id: Value(id),
      businessId: Value(businessId),
      branchId: branchId == null && nullToAbsent
          ? const Value.absent()
          : Value(branchId),
      documentType: Value(documentType),
      prefix: prefix == null && nullToAbsent
          ? const Value.absent()
          : Value(prefix),
      suffix: suffix == null && nullToAbsent
          ? const Value.absent()
          : Value(suffix),
      currentValue: Value(currentValue),
      step: Value(step),
      padding: Value(padding),
      resetFrequency: Value(resetFrequency),
      lastResetDate: lastResetDate == null && nullToAbsent
          ? const Value.absent()
          : Value(lastResetDate),
    );
  }

  factory Sequence.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Sequence(
      id: serializer.fromJson<String>(json['id']),
      businessId: serializer.fromJson<String>(json['businessId']),
      branchId: serializer.fromJson<String?>(json['branchId']),
      documentType: serializer.fromJson<String>(json['documentType']),
      prefix: serializer.fromJson<String?>(json['prefix']),
      suffix: serializer.fromJson<String?>(json['suffix']),
      currentValue: serializer.fromJson<int>(json['currentValue']),
      step: serializer.fromJson<int>(json['step']),
      padding: serializer.fromJson<int>(json['padding']),
      resetFrequency: serializer.fromJson<SequenceResetFrequency>(
        json['resetFrequency'],
      ),
      lastResetDate: serializer.fromJson<DateTime?>(json['lastResetDate']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'businessId': serializer.toJson<String>(businessId),
      'branchId': serializer.toJson<String?>(branchId),
      'documentType': serializer.toJson<String>(documentType),
      'prefix': serializer.toJson<String?>(prefix),
      'suffix': serializer.toJson<String?>(suffix),
      'currentValue': serializer.toJson<int>(currentValue),
      'step': serializer.toJson<int>(step),
      'padding': serializer.toJson<int>(padding),
      'resetFrequency': serializer.toJson<SequenceResetFrequency>(
        resetFrequency,
      ),
      'lastResetDate': serializer.toJson<DateTime?>(lastResetDate),
    };
  }

