class PayableEntry extends DataClass implements Insertable<PayableEntry> {
  /// Primary Key — UUID string stored as TEXT.
  final String id;

  /// Foreign Key component linking to business (`businesses.id`).
  final String businessId;

  /// Composite Foreign Key linking to `supplier_payables(business_id, id)` (CASCADE).
  final String supplierPayableId;

  /// Composite Foreign Key linking to `payments(business_id, id)` (SET NULL).
  final String? paymentId;

  /// Composite Foreign Key linking to `payment_allocations(business_id, id)` (SET NULL).
  final String? paymentAllocationId;

  /// Timestamp when this payable entry/allocation took place (`CURRENT_TIMESTAMP`).
  final DateTime entryDate;

  /// Amount allocated or adjusted in transaction currency (`decimal(18,2)`).
  final double amount;

  /// Amount allocated or adjusted in system base currency (`decimal(18,2)`).
  final double baseAmount;

  /// Type of payable entry (`Payment`, `Adjustment`, `WriteOff`).
  final String entryType;

  /// Foreign Key linking to the user who created the entry (`users.id`, RESTRICT).
  final String createdBy;

  /// Record creation timestamp (`CURRENT_TIMESTAMP`).
  final DateTime createdAt;

  /// Offline sync status tracking (`sync_status`).
  final String syncStatus;

  /// Local record modification version counter (`version`).
  final int version;

  /// Identifier of the device where the payable entry record was created or modified (`device_id`).
  final String? deviceId;
  const PayableEntry({
    required this.id,
    required this.businessId,
    required this.supplierPayableId,
    this.paymentId,
    this.paymentAllocationId,
    required this.entryDate,
    required this.amount,
    required this.baseAmount,
    required this.entryType,
    required this.createdBy,
    required this.createdAt,
    required this.syncStatus,
    required this.version,
    this.deviceId,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
