class Supplier extends DataClass implements Insertable<Supplier> {
  /// Primary Key — UUID string stored as TEXT.
  final String id;

  /// Foreign Key linking to `businesses.id` (RESTRICT).
  final String businessId;

  /// Full descriptive supplier or company display name.
  final String supplierName;

  /// Primary contact person name.
  final String? contactPerson;

  /// Contact phone number.
  final String? phone;

  /// Physical or office address of the supplier.
  final String? supplierAddress;

  /// Foreign Key linking to default purchasing currency (`currencies.id`, SET NULL).
  final String? defaultCurrencyId;

  /// Composite Foreign Key linking to `payment_terms(business_id, id)` (RESTRICT).
  final String? paymentTermId;

  /// Composite Foreign Key linking to accounting payable account (`chart_of_accounts(business_id, id)`, RESTRICT).
  final String? payableAccountId;

  /// Maximum credit ceiling allowed with the supplier (`decimal(18,2)`, check >= 0).
  final double creditLimit;

  /// Supplier opening balance amount (`decimal(18,2)`, check >= 0).
  final double openingBalance;

  /// Opening balance classification (`debit` or `credit`).
  final String? openingBalanceType;

  /// Date when the opening balance was established (`date`).
  final DateTime? openingBalanceDate;

  /// Operational activity status flag (`is_active`).
  final bool isActive;

  /// Record creation timestamp.
  final DateTime? createdAt;

  /// Record last update timestamp.
  final DateTime? updatedAt;

  /// Soft delete timestamp (`deleted_at`).
  final DateTime? deletedAt;

  /// Offline sync status tracking (`sync_status`).
  final String syncStatus;

  /// Local record modification version counter (`version`).
  final int version;

  /// Identifier of the device where the supplier record was created or modified (`device_id`).
  final String? deviceId;
  const Supplier({
    required this.id,
    required this.businessId,
    required this.supplierName,
    this.contactPerson,
    this.phone,
    this.supplierAddress,
    this.defaultCurrencyId,
    this.paymentTermId,
    this.payableAccountId,
    required this.creditLimit,
    required this.openingBalance,
    this.openingBalanceType,
    this.openingBalanceDate,
    required this.isActive,
    this.createdAt,
    this.updatedAt,
    this.deletedAt,
    required this.syncStatus,
    required this.version,
    this.deviceId,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['business_id'] = Variable<String>(businessId);
    map['supplier_name'] = Variable<String>(supplierName);
    if (!nullToAbsent || contactPerson != null) {
      map['contact_person'] = Variable<String>(contactPerson);
    }
    if (!nullToAbsent || phone != null) {
      map['phone'] = Variable<String>(phone);
    }
    if (!nullToAbsent || supplierAddress != null) {
      map['supplier_address'] = Variable<String>(supplierAddress);
    }
    if (!nullToAbsent || defaultCurrencyId != null) {
      map['default_currency_id'] = Variable<String>(defaultCurrencyId);
    }
    if (!nullToAbsent || paymentTermId != null) {
      map['payment_term_id'] = Variable<String>(paymentTermId);
    }
    if (!nullToAbsent || payableAccountId != null) {
      map['payable_account_id'] = Variable<String>(payableAccountId);
    }
    map['credit_limit'] = Variable<double>(creditLimit);
    map['opening_balance'] = Variable<double>(openingBalance);
