      map['opening_balance_type'] = Variable<String>(openingBalanceType);
    }
    if (!nullToAbsent || openingBalanceDate != null) {
      map['opening_balance_date'] = Variable<DateTime>(openingBalanceDate);
    }
    map['is_active'] = Variable<bool>(isActive);
