    required this.depreciationStartDate,
    required this.status,
    this.responsibleUserId,
    required this.createdBy,
    this.updatedBy,
    this.createdAt,
    this.updatedAt,
    required this.syncStatus,
    required this.version,
    this.deviceId,
  });
